package vn.edu.hcmute.bookstore_24110202.controller; import jakarta.servlet.annotation.*; import jakarta.servlet.http.*; import java.io.*; import vn.edu.hcmute.bookstore_24110202.entity.*; import vn.edu.hcmute.bookstore_24110202.service.impl.*; import vn.edu.hcmute.bookstore_24110202.util.*;
@WebServlet("/rating/create") public class RatingController_24110202 extends HttpServlet {private final RatingServiceImpl_24110202 r=new RatingServiceImpl_24110202();protected void doPost(HttpServletRequest q,HttpServletResponse p)throws IOException{q.setCharacterEncoding("UTF-8");User_24110202 u=(User_24110202)q.getSession(false).getAttribute("currentUser");Integer b=ValidationUtil_24110202.integer(q.getParameter("bookId")),score=ValidationUtil_24110202.integer(q.getParameter("rating"));String text=q.getParameter("reviewText");if(b==null||score==null||!ValidationUtil_24110202.rating(score.toString())||text==null||text.trim().isBlank()){q.getSession().setAttribute("flashError","Dữ liệu đánh giá không hợp lệ");}else if(r.exists(u.getId(),b)){q.getSession().setAttribute("flashError","Bạn đã đánh giá sách này");}else{r.save(u.getId(),b,score,text.trim());q.getSession().setAttribute("flashSuccess","Đã gửi đánh giá");}p.sendRedirect(q.getContextPath()+"/book/detail?id="+b);}}
